<template>
  <section class="adaptation-view">
    <header class="adaptation-header">
      <div><span class="eyebrow">小说 → 15 秒分镜</span><h2>自动改编工作台</h2><p>事实可追溯，节拍可编辑，镜头只在确认后进入生产。</p></div>
      <div class="header-actions">
        <span class="revision">R{{ workspace.revision }} · {{ workspace.facts.length }} 事实 · {{ workspace.beats.length }} 节拍</span>
        <select v-if="enabledProviders.length" v-model="selectedProviderId" class="provider-select"><option v-for="provider in enabledProviders" :key="provider.id" :value="provider.id">{{ provider.name }}</option></select>
        <button type="button" :disabled="busy" @click="providerDrawerOpen=true"><Settings2 :size="14" />模型连接</button>
        <button type="button" :disabled="busy" @click="createModelTask"><Bot :size="14" />{{ busyAction==='model-task' ? '规划中' : selectedProvider ? '规划分析批次' : '创建分析任务' }}</button>
        <button v-if="selectedProvider" type="button" :disabled="busy || !(activeRun?.nextTaskId || executableTask)" @click="executeModelTask"><Play :size="13" />{{ busyAction==='model-execute' ? '执行中' : activeRun?.nextTaskId ? `执行下一批 ${activeRun.completedBatches+1}/${activeRun.totalBatches}` : '执行模型' }}</button>
        <button v-if="replaceableTask" type="button" :disabled="busy" @click="replaceFailedBatch"><RefreshCcw :size="13" />替换失败批次 {{ replaceableTask.batchIndex }}</button>
        <button type="button" :disabled="busy" @click="analyze"><ScanText :size="14" />{{ busyAction === 'analyze' ? '分析中' : '分析真实章节' }}</button>
        <button class="primary-button" type="button" :disabled="busy || !workspace.beats.length" @click="generate"><WandSparkles :size="14" />{{ busyAction === 'generate' ? '规划中' : '生成两种方案' }}</button>
      </div>
    </header>

    <div class="adaptation-toolbar">
      <label><span>目标集</span><input v-model.number="episode" type="number" min="1" /></label>
      <label><span>起始 15s</span><input v-model.number="startUnit" type="number" min="1" /></label>
      <nav v-if="workspace.plans.length">
        <button v-for="plan in visiblePlans" :key="plan.id" type="button" :class="{active:activePlanId===plan.id}" @click="activePlanId=plan.id">
          <b>{{ plan.mode === 'concise' ? '精简模式' : '拆分模式' }}</b><small>{{ plan.units.length }} 单元 · {{ plan.units.reduce((sum,unit)=>sum+unit.storyboardRows.length,0) }} 镜</small>
        </button>
      </nav>
      <div class="toolbar-status" :class="{bad:activeValidation.hardErrors.length}"><ShieldCheck :size="14" />{{ activeValidation.hardErrors.length ? `${activeValidation.hardErrors.length} 个硬错误` : `${activeValidation.warnings.length} 个警告` }}</div>
    </div>

    <div v-if="workspace.analysisTasks.length || workspace.analysisReviews.length" class="review-bar">
      <div><ClipboardCheck :size="14" /><span>模型提案人工确认</span><b>{{ pendingReviews.length }} 待处理</b><small v-if="activeRun">长篇 {{ activeRun.completedBatches }}/{{ activeRun.totalBatches }} · {{ runStatusLabel(activeRun.status) }}</small><small v-else>{{ workspace.analysisTasks.length }} 个分析任务</small></div>
      <div class="review-ticker"><button v-for="review in pendingReviews.slice(0,4)" :key="review.id" type="button" :class="{bad:review.evidenceIssues.length}" @click="openReview(review)"><span>{{ review.kind==='fact'?'事实':'节拍' }}</span>{{ review.fact?.statement ?? review.beat?.title }}</button></div>
      <button type="button" @click="reviewDrawerOpen=!reviewDrawerOpen">{{ reviewDrawerOpen?'收起':'审核队列' }}</button>
    </div>

    <div v-if="changeImpact" class="impact-bar">
      <div><GitBranch :size="14" /><span>局部影响</span><b>{{ activeImpactUnitIds.length }} 个 15 秒单元 · {{ activeImpactRowIds.length }} 个镜头</b><small>其他单元不会重写</small></div>
      <button type="button" :disabled="busy || !activePlan || !activeImpactUnitIds.length" @click="regenerateScope"><WandSparkles :size="13" />{{ busyAction==='regenerate' ? '重生成中' : '仅重生成受影响单元' }}</button>
    </div>

    <div v-if="!workspace.facts.length" class="empty-stage">
      <GitBranch :size="34" /><b>先建立可追溯事实层</b><p>从已导入章节提取人物、对白、场景、时间、天气、服装、道具、心理和事件。模型推断不会伪装成原文事实。</p>
      <button class="primary-button" type="button" :disabled="busy" @click="analyze">分析真实章节</button>
    </div>

    <div v-else class="adaptation-grid">
      <aside class="facts-pane">
        <header><div><span>小说事实</span><b>{{ filteredFacts.length }}</b></div><label><Search :size="13" /><input v-model="factQuery" placeholder="筛选事实" /></label></header>
        <div class="fact-filters"><button type="button" :class="{active:factKind==='all'}" @click="factKind='all'">全部</button><button v-for="kind in factKinds" :key="kind" type="button" :class="{active:factKind===kind}" @click="factKind=kind">{{ factKindLabel(kind) }}</button></div>
        <div class="fact-list">
          <button v-for="fact in filteredFacts" :key="fact.id" type="button" :class="{active:selectedFactId===fact.id}" @click="selectFact(fact)"><span>{{ factKindLabel(fact.kind) }}</span><b>{{ fact.statement }}</b><small>{{ fact.epistemicStatus === 'confirmed' ? '原文确认' : fact.epistemicStatus === 'inferred' ? '明确推断' : '待确认' }} · R{{ fact.revision }}</small></button>
        </div>
        <form v-if="selectedFact" class="fact-editor" @submit.prevent="saveFact">
          <label><span>事实表述</span><textarea v-model="factDraft.statement" rows="4" /></label>
          <label><span>证据状态</span><select v-model="factDraft.epistemicStatus"><option value="confirmed">原文确认</option><option value="inferred">明确推断</option><option value="uncertain">待确认</option></select></label>
          <div class="source-evidence"><span>原文证据</span><p v-for="span in selectedFact.sourceSpans" :key="`${span.chapterId}-${span.startOffset}`">“{{ span.text }}”<small>{{ span.chapterId }} · {{ span.startOffset }}–{{ span.endOffset }}</small></p></div>
          <button type="submit" :disabled="busy"><Save :size="13" />保存局部事实</button>
        </form>
      </aside>

      <main class="beats-pane">
        <header><div><span>剧情节拍</span><b>{{ workspace.beats.length }}</b></div><p>选择节拍查看镜头映射；修改只影响后续重新生成。</p></header>
        <div class="beat-sequence">
          <button v-for="beat in workspace.beats" :key="beat.id" type="button" :class="{active:selectedBeatId===beat.id, hot:beat.intensity>=4}" @click="selectBeat(beat)"><span>{{ String(beat.order).padStart(2,'0') }}</span><div><b>{{ beat.title }}</b><p>{{ beat.narrativePurpose }}</p><small>{{ beat.estimatedDurationSeconds.toFixed(1) }}s · 强度 {{ beat.intensity }}/5 · {{ beat.factIds.length }} 事实</small></div><i></i></button>
        </div>
        <form v-if="selectedBeat" class="beat-editor" @submit.prevent="saveBeat">
          <div class="editor-heading"><span>节拍编辑</span><b>{{ selectedBeat.id }}</b></div>
          <div class="form-pair"><label><span>标题</span><input v-model="beatDraft.title" /></label><label><span>预计时长</span><input v-model.number="beatDraft.estimatedDurationSeconds" type="number" min="0.5" max="120" step="0.5" /></label></div>
          <label><span>叙事目的</span><input v-model="beatDraft.narrativePurpose" /></label>
          <label><span>可视化动作</span><textarea v-model="beatDraft.visualAction" rows="3" /></label>
          <div class="form-pair"><label><span>情绪变化</span><input v-model="beatDraft.emotionalShift" /></label><label><span>对白</span><input v-model="beatDraft.dialogue" /></label></div>
          <button type="submit" :disabled="busy"><Save :size="13" />保存节拍</button>
        </form>
      </main>

      <aside class="plan-pane">
        <template v-if="activePlan">
          <header><div><span>{{ activePlan.mode === 'concise' ? '精简方案' : '拆分方案' }}</span><b>{{ planStatus(activePlan.status) }}</b></div><p>{{ activePlan.mode === 'concise' ? '单个15秒单元，最多六镜，保留核心因果。' : '按节拍时长连续分组，保持跨单元连续性。' }}</p></header>
          <div class="plan-actions"><button v-if="activePlan.status==='draft'" type="button" :disabled="busy" @click="selectPlan"><Check :size="13" />选定方案</button><button v-if="activePlan.status==='selected'" class="primary-button" type="button" :disabled="busy || activeValidation.hardErrors.length>0" @click="materialize"><Boxes :size="13" />{{ activePlan.pendingUnitIds?.length ? `应用 ${activePlan.pendingUnitIds.length} 个局部单元` : '物化真实单元' }}</button><button type="button" :disabled="busy" @click="validate"><ShieldCheck :size="13" />校验</button></div>
          <div v-if="activeValidation.hardErrors.length || activeValidation.warnings.length" class="validation-list"><p v-for="issue in activeValidation.hardErrors" :key="issue" class="error"><XCircle :size="12" />{{ issue }}</p><p v-for="issue in activeValidation.warnings" :key="issue" class="warning"><TriangleAlert :size="12" />{{ issue }}</p></div>
          <div class="unit-list">
            <section v-for="unit in activePlan.units" :key="unit.id" :class="{active:selectedUnitId===unit.id}">
              <button type="button" @click="selectedUnitId=unit.id"><span>EP{{ pad(unit.episode) }} · 15s {{ pad(unit.unit,3) }}</span><b>{{ unit.title }}</b><small>{{ unit.durationSeconds.toFixed(1) }}s · {{ unit.storyboardRows.length }} 镜</small></button>
              <div v-if="selectedUnitId===unit.id" class="shot-list"><button v-for="row in unit.storyboardRows" :key="row.id" type="button" :class="{active:selectedShotId===row.id}" @click="selectedShotId=row.id"><span>{{ row.order }}</span><div><b>{{ row.shotSize }} · {{ row.cameraAngle }} · {{ row.lens }}</b><p>{{ row.action }}</p><small>{{ row.durationSeconds.toFixed(1) }}s · {{ row.cameraMovement }}</small></div></button></div>
            </section>
          </div>
          <div v-if="selectedShot" class="shot-inspector"><span>镜头生成合同</span><dl><div><dt>构图</dt><dd>{{ selectedShot.composition }}</dd></div><div><dt>调度</dt><dd>{{ selectedShot.staging }}</dd></div><div><dt>连续性</dt><dd>{{ selectedShot.continuityBefore }} → {{ selectedShot.continuityAfter }}</dd></div></dl><label><span>单张分镜图提示词</span><textarea :value="selectedShot.firstFramePrompt" readonly rows="4" /></label><label><span>图生视频提示词</span><textarea :value="selectedShot.videoPrompt" readonly rows="4" /></label></div>
          <footer><button type="button" @click="exportPlan('json')"><FileJson :size="13" />JSON</button><button type="button" @click="exportPlan('markdown')"><FileText :size="13" />Markdown</button><button type="button" @click="$emit('open-design')"><Clapperboard :size="13" />正式分镜编辑</button></footer>
        </template>
        <div v-else class="plan-empty"><Rows3 :size="28" /><b>尚未生成改编方案</b><p>完成事实和节拍分析后，同时生成精简与拆分模式。</p></div>
      </aside>
    </div>

    <aside v-if="reviewDrawerOpen" class="review-drawer">
      <header><div><span>模型提案</span><b>{{ pendingReviews.length }} 待确认</b></div><button type="button" @click="reviewDrawerOpen=false">×</button></header>
      <div class="review-batch-actions"><button type="button" :disabled="busy || !batchAcceptableReviews.length" @click="batchReview('accepted')"><Check :size="12" />接受可核验 {{ batchAcceptableReviews.length }}</button><button type="button" :disabled="busy || !batchRejectableReviews.length" @click="batchReview('rejected')"><XCircle :size="12" />拒绝证据异常 {{ batchRejectableReviews.length }}</button></div>
      <div class="review-queue"><button v-for="review in workspace.analysisReviews" :key="review.id" type="button" :class="{active:selectedReviewId===review.id,bad:review.evidenceIssues.length,done:review.status!=='pending'}" @click="openReview(review)"><span>{{ review.kind==='fact'?'事实':'节拍' }} · {{ review.status==='pending'?'待确认':review.status==='accepted'?'已接受':'已拒绝' }}</span><b>{{ review.fact?.statement ?? review.beat?.title }}</b><small>{{ review.evidenceIssues.length ? `${review.evidenceIssues.length} 个证据问题` : '原文区间校验通过' }}</small></button></div>
      <section v-if="selectedReview" class="review-inspector"><span>{{ selectedReview.kind==='fact'?'事实提案':'节拍提案' }}</span><h3>{{ selectedReview.fact?.statement ?? selectedReview.beat?.title }}</h3><p class="provider">{{ selectedReview.taskId }} · R{{ selectedReview.revision }}</p><div class="review-evidence"><p v-for="span in selectedReview.fact?.sourceSpans ?? selectedReview.beat?.sourceSpans ?? []" :key="`${span.chapterId}-${span.startOffset}`">“{{ span.text }}”<small>{{ span.chapterId }} · {{ span.startOffset }}–{{ span.endOffset }}</small></p></div><p v-for="issue in selectedReview.evidenceIssues" :key="issue" class="review-issue"><XCircle :size="12" />{{ issue }}</p><textarea v-model="reviewNote" rows="3" placeholder="审核说明（可选）" /><div v-if="selectedReview.status==='pending'" class="review-decisions"><button type="button" :disabled="busy || selectedReview.evidenceIssues.length>0" @click="decideReview('accepted')"><Check :size="13" />接受并写入</button><button type="button" :disabled="busy" @click="decideReview('rejected')"><XCircle :size="13" />拒绝</button></div><p v-else class="review-done">{{ selectedReview.status==='accepted'?'已写入事实/节拍层':'已拒绝且保留审计记录' }}</p></section>
    </aside>

    <aside v-if="providerDrawerOpen" class="provider-drawer">
      <header><div><span>小说分析模型</span><b>配置 R{{ providerSettings.revision }}</b></div><button type="button" @click="providerDrawerOpen=false">×</button></header>
      <div class="provider-list">
        <button v-for="provider in providerSettings.providers" :key="provider.id" type="button" :class="{active:providerDraft.id===provider.id}" @click="editProvider(provider)"><span>{{ provider.adapter==='mock'?'测试':'OpenAI Compatible' }}</span><b>{{ provider.name }}</b><small>{{ provider.model }} · R{{ provider.revision }} · {{ provider.enabled?'已启用':'停用' }}</small></button>
        <button type="button" class="new-provider" @click="newProvider">＋ 新建连接</button>
      </div>
      <form class="provider-editor" @submit.prevent="saveProvider">
        <div class="provider-warning"><ShieldCheck :size="14" /><p>密钥值不会落盘，只保存环境变量名。真实正文外发必须显式授权；公网必须使用 HTTPS，HTTP 仅允许显式授权的本机或私网服务。</p></div>
        <div class="form-pair"><label><span>Provider ID</span><input v-model="providerDraft.id" :disabled="Boolean(providerDraft.revision)" required /></label><label><span>显示名称</span><input v-model="providerDraft.name" required /></label></div>
        <div class="form-pair"><label><span>协议</span><select v-model="providerDraft.adapter"><option value="openai-compatible">OpenAI Compatible</option><option value="mock">本地测试 Mock</option></select></label><label><span>模型名</span><input v-model="providerDraft.model" required placeholder="例如 qwen3-30b-a3b" /></label></div>
        <label v-if="providerDraft.adapter==='openai-compatible'"><span>Base URL（包含 /v1）</span><input v-model="providerDraft.baseUrl" required placeholder="http://127.0.0.1:1234/v1" /></label>
        <div v-if="providerDraft.adapter==='openai-compatible'" class="form-pair"><label><span>密钥环境变量名</span><input v-model="providerDraft.apiKeyEnv" placeholder="OPENAI_API_KEY" /></label><label><span>最大输入字符</span><input v-model.number="providerDraft.maxInputCharacters" type="number" min="1000" max="2000000" /></label></div>
        <div class="provider-checks"><label><input v-model="providerDraft.enabled" type="checkbox" />启用</label><label v-if="providerDraft.adapter==='openai-compatible'"><input v-model="providerDraft.allowStoryUpload" type="checkbox" />我授权向该端点发送小说正文</label><label v-if="providerDraft.adapter==='openai-compatible'"><input v-model="providerDraft.allowPrivateNetwork" type="checkbox" />允许本机/私网地址</label><label v-if="providerDraft.adapter==='openai-compatible'"><input v-model="providerDraft.useJsonResponseFormat" type="checkbox" />请求 JSON response_format</label></div>
        <p v-if="providerMessage" class="provider-message">{{ providerMessage }}</p>
        <div class="provider-actions"><button type="submit" :disabled="busy"><Save :size="13" />保存连接</button><button v-if="providerDraft.revision" type="button" :disabled="busy" @click="probeProvider"><PlugZap :size="13" />{{ busyAction==='provider-probe'?'探测中':'探测 /models' }}</button></div>
      </form>
    </aside>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from "vue";
import { Bot, Boxes, Check, Clapperboard, ClipboardCheck, FileJson, FileText, GitBranch, Play, PlugZap, RefreshCcw, Rows3, Save, ScanText, Search, Settings2, ShieldCheck, TriangleAlert, WandSparkles, XCircle } from "lucide-vue-next";
import type { AdaptationChangeImpact, AdaptationPlan, AdaptationStore, AdaptationValidation, NarrativeBeat, NovelAnalysisProvider, NovelAnalysisProviderSettings, NovelAnalysisReviewItem, NovelAnalysisRunProgress, NovelFact, NovelFactKind, ProjectIndex, StoryboardRow } from "@core/types";

const props=defineProps<{projectRoot:string;index:ProjectIndex}>();
const emit=defineEmits<{changed:[message:string];failed:[message:string];"open-design":[]}>();
const empty=():AdaptationStore=>({schemaVersion:1,revision:0,sourceLibraryRevision:0,facts:[],beats:[],plans:[],analysisTasks:[],analysisReviews:[],updatedAt:new Date(0).toISOString()});
const workspace=ref<AdaptationStore>(empty());const activePlanId=ref("");const selectedFactId=ref("");const selectedBeatId=ref("");const selectedUnitId=ref("");const selectedShotId=ref("");const busyAction=ref("");const factQuery=ref("");const factKind=ref<NovelFactKind|"all">("all");const episode=ref(1);const startUnit=ref(1);const validationOverride=ref<AdaptationValidation|null>(null);const changeImpact=ref<AdaptationChangeImpact|null>(null);const reviewDrawerOpen=ref(false);const selectedReviewId=ref("");const reviewNote=ref("");const providerDrawerOpen=ref(false);const selectedProviderId=ref("");const providerMessage=ref("");
const providerSettings=ref<NovelAnalysisProviderSettings>({schemaVersion:1,revision:0,providers:[],updatedAt:new Date(0).toISOString()});
const analysisRuns=ref<NovelAnalysisRunProgress[]>([]);
const providerDraft=reactive({id:"",name:"",adapter:"openai-compatible" as NovelAnalysisProvider["adapter"],enabled:true,baseUrl:"http://127.0.0.1:1234/v1",model:"",apiKeyEnv:"",allowPrivateNetwork:true,allowStoryUpload:false,useJsonResponseFormat:true,timeoutSeconds:120,maxInputCharacters:200000,temperature:0,revision:0});
const factDraft=reactive({statement:"",epistemicStatus:"confirmed" as NovelFact["epistemicStatus"]});
const beatDraft=reactive({title:"",narrativePurpose:"",visualAction:"",emotionalShift:"",dialogue:"",estimatedDurationSeconds:4});
const busy=computed(()=>Boolean(busyAction.value));
const factKinds:NovelFactKind[]=["character","relationship","location","time","weather","costume","prop","dialogue","psychology","environment","event","rule"];
const filteredFacts=computed(()=>workspace.value.facts.filter(f=>(factKind.value==="all"||f.kind===factKind.value)&&(!factQuery.value||`${f.statement} ${f.tags.join(" ")}`.includes(factQuery.value))));
const selectedFact=computed(()=>workspace.value.facts.find(f=>f.id===selectedFactId.value));const selectedBeat=computed(()=>workspace.value.beats.find(b=>b.id===selectedBeatId.value));
const visiblePlans=computed(()=>[...workspace.value.plans].sort((a,b)=>a.mode.localeCompare(b.mode)).slice(0,2));
const activePlan=computed(()=>workspace.value.plans.find(p=>p.id===activePlanId.value));
const activeValidation=computed(()=>validationOverride.value??activePlan.value?.validation??{hardErrors:[],warnings:[],checkedAt:""});
const selectedUnit=computed(()=>activePlan.value?.units.find(u=>u.id===selectedUnitId.value));
const selectedShot=computed<StoryboardRow|undefined>(()=>selectedUnit.value?.storyboardRows.find(r=>r.id===selectedShotId.value));
const pendingReviews=computed(()=>workspace.value.analysisReviews.filter(review=>review.status==="pending"));const selectedReview=computed(()=>workspace.value.analysisReviews.find(review=>review.id===selectedReviewId.value));
const batchAcceptableReviews=computed(()=>{const factReviews=workspace.value.analysisReviews.filter(review=>review.kind==="fact"&&review.fact);return pendingReviews.value.filter(review=>!review.evidenceIssues.length&&(review.kind==="fact"||(review.beat?.factIds.every(id=>workspace.value.facts.some(fact=>fact.id===id)||factReviews.some(candidate=>candidate.fact?.id===id&&(candidate.status==="accepted"||(candidate.status==="pending"&&!candidate.evidenceIssues.length))))??false)))});const batchRejectableReviews=computed(()=>pendingReviews.value.filter(review=>review.evidenceIssues.length));
const enabledProviders=computed(()=>providerSettings.value.providers.filter(provider=>provider.enabled));const selectedProvider=computed(()=>enabledProviders.value.find(provider=>provider.id===selectedProviderId.value));const activeRun=computed(()=>analysisRuns.value.find(run=>run.providerId===selectedProviderId.value&&run.status!=="completed")??analysisRuns.value.find(run=>run.providerId===selectedProviderId.value));const executableTask=computed(()=>workspace.value.analysisTasks.find(task=>!task.runId&&task.providerId===selectedProviderId.value&&task.status==="prepared"&&!task.execution));const replaceableTask=computed(()=>{const run=activeRun.value;if(!run||run.status!=="blocked")return undefined;return workspace.value.analysisTasks.filter(task=>task.runId===run.runId&&!task.replacedByTaskId&&(task.status==="failed"||task.status==="submission_unknown")).sort((left,right)=>(right.attempt??1)-(left.attempt??1))[0]});
const activePlanImpact=computed(()=>changeImpact.value?.plans.find(plan=>plan.planId===activePlanId.value));
const activeImpactUnitIds=computed(()=>activePlanImpact.value?.unitIds??[]);const activeImpactRowIds=computed(()=>activePlanImpact.value?.rowIds??[]);
async function load(){changeImpact.value=null;try{[workspace.value,providerSettings.value,analysisRuns.value]=await Promise.all([window.canvasApi.getAdaptationWorkspace(props.projectRoot),window.canvasApi.getNovelAnalysisProviders(props.projectRoot),window.canvasApi.listNovelAnalysisRuns(props.projectRoot)]);if(!enabledProviders.value.some(provider=>provider.id===selectedProviderId.value))selectedProviderId.value=providerSettings.value.defaultProviderId??enabledProviders.value[0]?.id??"";syncPlan();if(!workspace.value.facts.some(f=>f.id===selectedFactId.value)&&workspace.value.facts[0])selectFact(workspace.value.facts[0]);if(!workspace.value.beats.some(b=>b.id===selectedBeatId.value)&&workspace.value.beats[0])selectBeat(workspace.value.beats[0])}catch(error){emit("failed",message(error));}}
function syncPlan(){if(!workspace.value.plans.some(p=>p.id===activePlanId.value))activePlanId.value=workspace.value.selectedPlanId??visiblePlans.value[0]?.id??"";const plan=activePlan.value;if(plan&&!plan.units.some(u=>u.id===selectedUnitId.value))selectedUnitId.value=plan.units[0]?.id??"";const unit=selectedUnit.value;if(unit&&!unit.storyboardRows.some(r=>r.id===selectedShotId.value))selectedShotId.value=unit.storyboardRows[0]?.id??"";validationOverride.value=null;}
async function run(action:string,operation:()=>Promise<void>){busyAction.value=action;try{await operation()}catch(error){emit("failed",message(error))}finally{busyAction.value=""}}
async function analyze(){await run("analyze",async()=>{workspace.value=await window.canvasApi.analyzeNovelChapters(props.projectRoot,{expectedRevision:workspace.value.revision});changeImpact.value=null;syncPlan();emit("changed",`真实章节分析完成：${workspace.value.facts.length} 条事实，${workspace.value.beats.length} 个节拍`)})}
async function createModelTask(){await run("model-task",async()=>{const provider=selectedProvider.value;if(provider){const result=await window.canvasApi.planNovelAnalysisRun(props.projectRoot,{expectedRevision:workspace.value.revision,providerId:provider.id});workspace.value=result.workspace;analysisRuns.value=await window.canvasApi.listNovelAnalysisRuns(props.projectRoot);emit("changed",`${provider.name} 已规划 ${result.tasks.length} 个顺序批次，共 ${result.progress.plannedCharacterCount} 字符`)}else{const result=await window.canvasApi.createNovelAnalysisTask(props.projectRoot,{expectedRevision:workspace.value.revision,providerId:"codex",providerKind:"codex"});workspace.value=result.workspace;emit("changed",`Codex 小说分析任务已落盘：${result.task.taskMarkdownPath}`)}})}
async function executeModelTask(){const provider=selectedProvider.value;if(!provider)return;await run("model-execute",async()=>{const runProgress=activeRun.value;const task=executableTask.value;const result=runProgress?.nextTaskId?await window.canvasApi.executeNextNovelAnalysisRunTask(props.projectRoot,{runId:runProgress.runId,expectedRevision:workspace.value.revision}):task?await window.canvasApi.executeNovelAnalysisTask(props.projectRoot,{taskId:task.id,providerId:provider.id,expectedRevision:workspace.value.revision}):null;if(!result)return;workspace.value=result.workspace;analysisRuns.value=await window.canvasApi.listNovelAnalysisRuns(props.projectRoot);if(result.outcome==="reviewing"){reviewDrawerOpen.value=true;selectedReviewId.value=pendingReviews.value[0]?.id??"";emit("changed",`模型返回 ${result.reviewCount} 条提案，已进入人工确认队列；人工确认后才解锁下一批`)}else if(result.outcome==="submission_unknown")emit("failed","模型请求回执不明，已锁定该批次且不会自动重提；请先对账") ;else emit("failed",result.task.execution?.error??"模型分析执行失败")})}
async function replaceFailedBatch(){const task=replaceableTask.value;if(!task||!task.runId||!task.batchIndex)return;const reason=window.prompt("请输入替换该失败批次的原因。旧任务和错误记录会保留：",task.status==="submission_unknown"?"已在 Provider 后台对账，确认无可回收结果":"已修正模型服务或输出错误");if(!reason?.trim())return;let confirmNoRemoteResult=false;if(task.status==="submission_unknown"){confirmNoRemoteResult=window.confirm("只有在你已经核对 Provider 后台，并确认该请求没有可回收结果时才能创建新尝试。是否确认？");if(!confirmNoRemoteResult)return;}await run("model-replace",async()=>{const result=await window.canvasApi.replaceNovelAnalysisRunTask(props.projectRoot,{runId:task.runId!,batchIndex:task.batchIndex!,expectedRevision:workspace.value.revision,reason,confirmNoRemoteResult});workspace.value=result.workspace;analysisRuns.value=await window.canvasApi.listNovelAnalysisRuns(props.projectRoot);emit("changed",`批次 ${task.batchIndex} 已创建第 ${result.task.attempt} 次尝试；旧任务完整保留`)})}
function newProvider(){Object.assign(providerDraft,{id:"",name:"",adapter:"openai-compatible",enabled:true,baseUrl:"http://127.0.0.1:1234/v1",model:"",apiKeyEnv:"",allowPrivateNetwork:true,allowStoryUpload:false,useJsonResponseFormat:true,timeoutSeconds:120,maxInputCharacters:200000,temperature:0,revision:0});providerMessage.value=""}
function editProvider(provider:NovelAnalysisProvider){Object.assign(providerDraft,{...provider,baseUrl:provider.baseUrl??"",apiKeyEnv:provider.apiKeyEnv??""});providerMessage.value=""}
async function saveProvider(){await run("provider-save",async()=>{providerSettings.value=await window.canvasApi.upsertNovelAnalysisProvider(props.projectRoot,{expectedRevision:providerSettings.value.revision,provider:{id:providerDraft.id,name:providerDraft.name,adapter:providerDraft.adapter,enabled:providerDraft.enabled,baseUrl:providerDraft.baseUrl||undefined,model:providerDraft.model,apiKeyEnv:providerDraft.apiKeyEnv||undefined,allowPrivateNetwork:providerDraft.allowPrivateNetwork,allowStoryUpload:providerDraft.allowStoryUpload,useJsonResponseFormat:providerDraft.useJsonResponseFormat,timeoutSeconds:providerDraft.timeoutSeconds,maxInputCharacters:providerDraft.maxInputCharacters,temperature:providerDraft.temperature,...(providerDraft.revision?{revision:providerDraft.revision}:{})},setAsDefault:true});selectedProviderId.value=providerDraft.id;const saved=providerSettings.value.providers.find(provider=>provider.id===providerDraft.id);if(saved)editProvider(saved);providerMessage.value="连接配置已保存；项目文件中没有密钥值。";emit("changed",`小说分析模型已保存：${providerDraft.name}`)})}
async function probeProvider(){if(!providerDraft.id)return;await run("provider-probe",async()=>{const result=await window.canvasApi.probeNovelAnalysisProvider(props.projectRoot,providerDraft.id);providerMessage.value=`探测成功 · ${result.latencyMs}ms · ${result.models.length?result.models.slice(0,3).join("、"):"服务未列出模型"}`;emit("changed",`${providerDraft.name} 模型服务可达`)})}
async function generate(){await run("generate",async()=>{const result=await window.canvasApi.generateAdaptationPlans(props.projectRoot,{expectedRevision:workspace.value.revision,episode:episode.value,startUnit:startUnit.value});workspace.value=result.workspace;changeImpact.value=null;activePlanId.value=result.plans.find(p=>p.mode==="split")?.id??result.plans[0]?.id??"";syncPlan();emit("changed","精简与拆分两种改编方案已生成")})}
async function selectPlan(){if(!activePlan.value)return;await run("select",async()=>{workspace.value=await window.canvasApi.selectAdaptationPlan(props.projectRoot,activePlan.value!.id,workspace.value.revision);syncPlan();emit("changed","改编方案已选定，等待物化真实单元")})}
async function materialize(){await run("materialize",async()=>{const result=await window.canvasApi.materializeAdaptationPlan(props.projectRoot,{expectedRevision:workspace.value.revision});workspace.value=result.workspace;syncPlan();emit("changed",`已物化 ${result.unitPaths.length} 个真实15秒单元和 ${result.storyboardRows.length} 个草稿镜头`)})}
async function regenerateScope(){if(!activePlan.value||!changeImpact.value)return;await run("regenerate",async()=>{const result=await window.canvasApi.regenerateAdaptationScope(props.projectRoot,{planId:activePlan.value!.id,expectedRevision:workspace.value.revision,factIds:changeImpact.value!.changedFactIds,beatIds:changeImpact.value!.changedBeatIds});workspace.value=result.workspace;syncPlan();changeImpact.value=null;emit("changed",`仅重生成 ${result.regeneratedUnitIds.length} 个受影响单元；请应用局部单元`)})}
function openReview(review:NovelAnalysisReviewItem){selectedReviewId.value=review.id;reviewNote.value=review.decisionNote??"";reviewDrawerOpen.value=true}
async function decideReview(decision:"accepted"|"rejected"){const review=selectedReview.value;if(!review)return;await run("review",async()=>{const result=await window.canvasApi.reviewNovelAnalysisItem(props.projectRoot,{reviewId:review.id,decision,expectedRevision:workspace.value.revision,reviewExpectedRevision:review.revision,note:reviewNote.value||undefined});workspace.value=result.workspace;analysisRuns.value=await window.canvasApi.listNovelAnalysisRuns(props.projectRoot);const next=pendingReviews.value[0];selectedReviewId.value=next?.id??result.review.id;reviewNote.value="";syncPlan();emit("changed",decision==="accepted"?"模型提案已核验并写入事实/节拍层":"模型提案已拒绝并保留审计记录")})}
async function batchReview(decision:"accepted"|"rejected"){const targets=decision==="accepted"?batchAcceptableReviews.value:batchRejectableReviews.value;if(!targets.length||!window.confirm(decision==="accepted"?`批量接受 ${targets.length} 条证据可核验提案？系统会先写事实再写节拍。`:`批量拒绝 ${targets.length} 条证据异常提案？`))return;await run("review-batch",async()=>{const result=await window.canvasApi.reviewNovelAnalysisBatch(props.projectRoot,{expectedRevision:workspace.value.revision,decisions:targets.map(review=>({reviewId:review.id,decision,reviewExpectedRevision:review.revision,note:decision==="accepted"?"批量证据校验通过":"批量拒绝证据异常"}))});workspace.value=result.workspace;analysisRuns.value=await window.canvasApi.listNovelAnalysisRuns(props.projectRoot);selectedReviewId.value=pendingReviews.value[0]?.id??result.reviews[0]?.id??"";syncPlan();emit("changed",decision==="accepted"?`已按事实→节拍顺序接受 ${result.reviews.length} 条提案`:`已拒绝 ${result.reviews.length} 条证据异常提案`)})}
async function validate(){if(!activePlan.value)return;await run("validate",async()=>{validationOverride.value=await window.canvasApi.validateAdaptationPlan(props.projectRoot,activePlan.value!.id);emit("changed",validationOverride.value.hardErrors.length?"校验发现硬错误":"改编计划硬校验通过")})}
function selectFact(fact:NovelFact){selectedFactId.value=fact.id;factDraft.statement=fact.statement;factDraft.epistemicStatus=fact.epistemicStatus;const beat=workspace.value.beats.find(b=>b.factIds.includes(fact.id));if(beat)selectedBeatId.value=beat.id;}
function selectBeat(beat:NarrativeBeat){selectedBeatId.value=beat.id;Object.assign(beatDraft,{title:beat.title,narrativePurpose:beat.narrativePurpose,visualAction:beat.visualAction,emotionalShift:beat.emotionalShift,dialogue:beat.dialogue??"",estimatedDurationSeconds:beat.estimatedDurationSeconds});selectedFactId.value=beat.factIds[0]??selectedFactId.value;const unit=activePlan.value?.units.find(u=>u.beatIds.includes(beat.id));if(unit){selectedUnitId.value=unit.id;selectedShotId.value=unit.storyboardRows.find(r=>r.upstreamBeatRefs?.some(ref=>ref.id===beat.id))?.id??unit.storyboardRows[0]?.id??"";}}
async function saveFact(){const fact=selectedFact.value;if(!fact)return;await run("fact",async()=>{await window.canvasApi.upsertNovelFact(props.projectRoot,{...fact,statement:factDraft.statement,epistemicStatus:factDraft.epistemicStatus,expectedRevision:fact.revision});await load();changeImpact.value=await window.canvasApi.analyzeAdaptationImpact(props.projectRoot,{factIds:[fact.id]});emit("changed",`事实已保存；识别到 ${changeImpact.value.affectedUnitIds.length} 个受影响单元`)})}
async function saveBeat(){const beat=selectedBeat.value;if(!beat)return;await run("beat",async()=>{await window.canvasApi.upsertNarrativeBeat(props.projectRoot,{...beat,title:beatDraft.title,narrativePurpose:beatDraft.narrativePurpose,visualAction:beatDraft.visualAction,emotionalShift:beatDraft.emotionalShift,dialogue:beatDraft.dialogue||undefined,estimatedDurationSeconds:beatDraft.estimatedDurationSeconds,expectedRevision:beat.revision});await load();changeImpact.value=await window.canvasApi.analyzeAdaptationImpact(props.projectRoot,{beatIds:[beat.id]});emit("changed",`节拍已保存；识别到 ${changeImpact.value.affectedUnitIds.length} 个受影响单元`)})}
async function exportPlan(format:"json"|"markdown"){if(!activePlan.value)return;await run("export",async()=>{const ext=format==="json"?"json":"md";const version=new Date().toISOString().replace(/[-:TZ.]/g,"").slice(0,14);const outputPath=`${props.projectRoot}/小说自动分镜_${activePlan.value!.mode}_${version}.${ext}`;const result=await window.canvasApi.exportAdaptation(props.projectRoot,{format,outputPath,planId:activePlan.value!.id});emit("changed",`已导出：${result.path}`)})}
function factKindLabel(kind:NovelFactKind){return({event:"事件",character:"人物",location:"场景",prop:"道具",rule:"规则",dialogue:"对白",relationship:"关系",time:"时间",weather:"天气",costume:"服装",narration:"旁白",psychology:"心理",environment:"环境"})[kind]}
function runStatusLabel(status:NovelAnalysisRunProgress["status"]){return({ready:"待执行",running:"执行中",awaiting_review:"待人工确认",completed:"已完成",blocked:"已阻塞",stale:"已失效"})[status]}
function planStatus(status:AdaptationPlan["status"]){return({draft:"草稿",selected:"已选定",materialized:"已物化"})[status]}
function pad(value:number,length=2){return String(value).padStart(length,"0")}function message(error:unknown){return error instanceof Error?error.message:String(error)}
watch(()=>props.projectRoot,load);watch(activePlanId,syncPlan);onMounted(load);
</script>

